inet", npcObj=true}, [26]={hint="Loot from: Farmer Dalson"}, [27]={npc="Locked Cabinet", npcObj=true}, [29]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it."}, [30]={npc="High Executor Derrington", tgt="High Executor Derrington"}, [31]={hint="Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."}, [32]={npc="Shadow Priestess Vandis", tgt="Shadow Priestess Vandis"}, [34]={hint="Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration."}, [35]={npc="Royal Overseer Bauhaus", tgt="Royal Overseer Bauhaus"}, [36]={npc="Royal Overseer Bauhaus", tgt="Royal Overseer Bauhaus"}, [37]={hint="Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone. If he is, then perhaps he'd like the package Janice Felstone made for him."}, [38]={npc="Jeremiah Payson", tgt="Jeremiah Payson"}, [39]={npc="Jeremiah Payson", tgt="Jeremiah Payson"}, [40]={npc="Knight of Mourning", tag="Optional, Unverified"}, [41]={hint="Speak with the Knight of Mourning to learn more about his unfinished quest.", tag="Optional, Unverified"}, [42]={npc="Knight of Mourning", tag="Optional, Unverified"}, [43]={npc="Knight of Mourning", tag="Optional, Unverified"}, [44]={hint="Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", tag="Optional"}, [45]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional"}, [46]={npc="Bath'rah the Windwatcher", tgt="Bath'rah the Windwatcher", tag="Optional", star={"Enamored Water Spirit", {"SHAMAN"}}}}},
