    [4787] = {n="The Ancient Egg", d="Bring the Ancient Egg to Yeh'kinya in Tanaris.", objs={"Ancient Egg"}},
    [4808] = {n="Felnok Steelspring", d="Give Tinkee's Letter to Felnok Steelspring."},
    [4809] = {n="Chillwind Horns", d="Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", tgo={{"Fledgling Chillwind", "Chillwind Chimaera", "Chillwind Ravager"}}},
    [4810] = {n="Return to Tinkee", d="Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes."},
    [4821] = {n="Alien Egg", d="Return the Alien Egg to Hagar Lightninghoof in Freewind Post.", objs={"Alien Egg"}},
    [4841] = {n="Pacify the Centaur", d="Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.", tgo={{"Galak Scout"}, {"Galak Wrangler"}, {"Galak Windchaser"}}},
    [4842] = {n="Strange Sources", d="Follow Donova Snowden's instructions, then report back."},
    [4862] = {n="En-Ay-Es-Tee-Why", d="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\nBy the sound of it, these eggs could be found near spiders.", objs={"Spire Spider Egg"}},
    [4865] = {n="Serpent Wild", d="Report your findings to Motega Firemane."},
    [4881] = {n="Assassination Plot", d="Warn Kanati Greycloud at Whitereach Post of the plot to kill him."},
    [4903] = {n="Warlord's Command", d="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", tgo={{"Overlord Wyrmthalak"}, {"Highlord Omokk"}, {"War Master Voone"}, {}}, objs={"Inconspicuous Documents"}},
    [4904] = {n="Free at Last", d="Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post."},
    [4921] = {n="Lost in Battle", d="Find Mankrik's wife and then return to him in the Crossroads.", tgo={{"Beaten Corpse"}}},
    [4941] = {n="Eitrigg's Wisdom", d="Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.\nYou recall having seen Eitrigg in Thrall's chamber."},
    [4961] = {n="Cleansing of the Orb of Orahil", d="Kill the Demon of the Orb, then speak with Tabetha.", tgo={{"Demon of the Orb"}}},
    [4962] = {n="Shard of a Felhound", d="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", tgo={{"Mana Eater"}}},
    [4963] = {n="Shard of an Infernal", d="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.", tgo={{"Lesser Infernal"}}},
    [4964] = {n="The Completed Orb of Dar'Orahil", d="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4966] = {n="Protect Kanati Greycloud", d="Protect Kanati Greycloud from the centaur attack.", tgo={{"Galak Assassin"}}},
    [4967] = {n="Knowledge of the Orb of Orahil", d="Speak to Menara Voidrender in the Barrens."},
    [4969] = {n="Knowledge of the Orb of Orahil", d="Speak to Menara Voidrender in the Barrens."},
    [4971] = {n="A Matter of Time", d="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\nSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.", tgo={{"Temporal Parasite"}}},
    [4972] = {n="Counting Out Time", d="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands.", objs={"Small Lockbox"}},
    [4974] = {n="For The Horde!", d="Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", tgo={{"Warchief Rend Blackhand"}}},
    [4975] = {n="The Completed Orb of Noh'Orahil", d="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Returning the Cleansed Orb", d="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens."},
    [4981] = {n="Operative Bijou", d="Travel to Blackrock Spire and find out what happened to Bijou."},
    [4982] = {n="Bijou's Belongings", d="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.", objs={"Bijou's Belongings"}},
    [4983] = {n="Bijou's Reconnaissance Report", d="Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath."},
    [4984] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Wolf"}}},
    [4985] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Grizzly"}}},
    [5021] = {n="Better Late Than Never", d="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."},
    [5023] = {n="Better Late Than Never", d="Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration."},
    [5041] = {n="Supplies for the Crossroads", d="Find and return Crossroads' Supply Crates to Thork in the Barrens.", objs={"Crossroads' Supply Crates"}},
    [5049] = {n="The Jeremiah Blues", d="Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone. If he is, then perhaps he'd like the package Janice Felstone made for him."},
    [5050] = {n="Good Luck Charm", d="Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm."},
    [5051] = {n="Two Halves Become One", d="Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.\nGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands."},
    [5052] = {n="Blood Shards of Agamaggan", d="Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.\nCollect more Blood Shards if you want him to bless you with Agamaggan's power.", tgo={{"Bristleback Hunter", "Bristleback Water Seeker", "Bristleback Thornweaver"}}},
    [5054] = {n="Ursius of the Shardtooth", d="Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius.", tgo={{"Ursius"}}},
    [5058] = {n="Mrs. Dalson's Diary"},
    [5059] = {n="Locked Away", d="Loot from: Wandering Skeleton", tgo={{"Wandering Skeleton"}}},
    [5060] = {n="Locked Away", d="Loot from: Farmer Dalson", tgo={{"Farmer Dalson"}}},
    [5062] = {n="Sacred Fire", d="Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.", objs={"Incendia Agave"}},
    [5064] = {n="Grimtotem Spying", d="Locate and retrieve the three Secret Notes in Darkcloud Pinnacle.", objs={"Document Chest"}},
    [5082] = {n="Threat of the Winterfall", d="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.", tgo={{"Winterfall Pathfinder"}, {"Winterfall Den Watcher"}, {"Winterfall Totemic"}}},
    [5083] = {n="Winterfall Firewater", d="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."},
    [5084] = {n="Falling to Corruption", d="Search the Deadwood furbolg camp in northern Felwood for a clue."},
    [5085] = {n="Mystery Goo", d="Report back to Donova Snowden with your findings."},
    [5086] = {n="Toxic Horrors", d="Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.", tgo={{"Toxic Horror"}}},
    [5087] = {n="Winterfall Runners", d="Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.", tgo={{"Winterfall Runner"}}},
    [5096] = {n="Scarlet Diversions", d="Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.\nPlace the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands."},
    [5098] = {n="All Along the Watchtowers", d="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.", tgo={{"Andorhal Tower One"}, {"Andorhal Tower Two"}, {"Andorhal Tower Three"}, {"Andorhal Tower Four"}}},
    [5121] = {n="High Chief Winterfall", d="Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.", tgo={{"High Chief Winterfall"}}},
    [5122] = {n="The Medallion of Faith", d="Use/collect: Malor's Strongbox", objs={"Malor's Strongbox"}},
    [5123] = {n="The Final Piece", d="Bring the Crudely-written Log to Donova Snowden in Winterspring."},
    [5125] = {n="Aurius' Reckoning"},
    [5147] = {n="WANTED: Arnak Grimtotem", d="Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.", tgo={{"Arnak Grimtotem"}}},
    [5149] = {n="Pamela's Doll", d="Find Pamela's doll."},
    [5151] = {n="Hypercapacitor Gizmo", d="Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.", tgo={{"Enraged Panther"}}},
    [5152] = {n="Auntie Marlene", d="Speak with Marlene, south of the Ruins of Andorhal."},
    [5153] = {n="A Strange Historian", d="Bring Joseph's Wedding Ring to Chromie.", objs={"Joseph Redpath's Monument"}},
    [5154] = {n="The Annals of Darrowshire", d="Bring the Annals of Darrowshire to Chromie in Andorhal.", objs={"Musty Tome"}},
    [5155] = {n="Forces of Jaedenar", d="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", tgo={{"Jaedenar Hound"}, {"Jaedenar Guardian"}, {"Jaedenar Adept"}, {"Jaedenar Cultist"}}},
    [5156] = {n="Verifying the Corruption", d="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", tgo={{"Entropic Beast"}, {"Entropic Horror"}}},
    [5157] = {n="Collection of the Corrupt Water", d="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", objs={"Corrupt Jaedenar Moonwell"}},
    [5158] = {n="Seeking Spiritual Aid", d="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."},
    [5159] = {n="Cleansed Water Returns to Felwood", d="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."},
    [5163] = {n="Are We There, Yeti?", d="Take Umi's Mechanical Yeti and scare her friends with it:\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshal's Refuge (Un'Goro Crater)\nWhen you are done, bring the Mechanical Yeti back to Umi.", tgo={{"Legacki"}, {"Sprinkle"}, {"Quixxil"}}},
    [5165] = {n="Dousing the Flames of Protection", d="Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.", objs={"Brazier of Pain", "Brazier of Malice", "Brazier of Suffering", "Brazier of Hatred"}},
    [5211] = {n="Defenders of Darrowshire", d="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tgo={{"Darrowshire Spirit"}}},
    [5212] = {n="The Flesh Does Not Lie", d="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", tgo={{"Ravaged Cadaver", "Mangled Cadaver", "Plague Ghoul"}}},
    [5213] = {n="The Active Agent", d="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", objs={"Scourge Data"}},
    [5214] = {n="The Great Ezra Grimm", d="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", tgo={{"Ezra Grimm"}}},
    [5228] = {n="The Scourge Cauldrons", d="Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
    [5229] = {n="Target: Felstone Field", d="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Bilemaw"}}},
    [5230] = {n="Return to the Bulwark", d="Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
    [5231] = {n="Target: Dalson's Tears", d="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Malvinious"}}},
    [5232] = {n="Return to the Bulwark", d="Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
    [5233] = {n="Target: Writhing Haunt", d="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Razarch"}}},
    [5234] = {n="Return to the Bulwark", d="Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands."},
    [5235] = {n="Target: Gahrron's Withering", d="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Soulwrath"}}},
    [5236] = {n="Return to the Bulwark", d="Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
    [5238] = {n="Mission Accomplished!", star={"Valiant Shortsword", {"PALADIN", "MAGE", "WARLOCK"}}},
    [5241] = {n="Uncle Carlin", d="Find Carlin Redpath."},
    [5242] = {n="A Final Blow", d="Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.", tgo={{"Moora"}, {"Salia"}, {"Shadow Lord Fel'dan"}}},
    [5243] = {n="Houses of the Holy", d="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", objs={"Supply Crate", "Stratholme Supply Crate"}},
    [5251] = {n="The Archivist", d="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", tgo={{"Archivist Galford"}, {}}, objs={"Scarlet Archive"}},
    [5281] = {n="The Restless Souls", d="Find Egan. You only know that he was last seen around Stratholme."},
    [5282] = {n="The Restless Souls", d="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\nFree 15 Restless Souls and return to Egan.", tgo={{"Restless Soul"}}},
    [5306] = {n="Snakestone of the Shadow Huntress", d="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", tgo={{"Shadow Hunter Vosh'gajin"}}},
    [5341] = {n="Barov Family Fortune", d="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", objs={"The Deed to Brill", "The Deed to Caer Darrow", "The Deed to Southshore", "The Deed to Tarren Mill"}},
    [5361] = {n="Family Tree", d="Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace."},
    [5381] = {n="Hand of Iruxos", d="Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.", tgo={{"Demon Spirit"}}},
    [5382] = {n="Doctor Theolen Krastinov, the Butcher", d="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", tgo={{"Doctor Theolen Krastinov"}, {}, {}}, objs={"Remains of Eva Sarkhoff", "Remains of Lucien Sarkhoff"}},
    [5386] = {n="Catch of the Day", d="Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.", tgo={{"Jinar'Zillen"}}},
    [5441] = {n="Lazy Peons", d="Use the Foreman's Blackjack on Lazy Peons when they're sleeping. Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.", tgo={{"Lazy Peon"}}},
    [5481] = {n="Gordo's Task", d="Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard.", objs={"Gloom Weed"}},
    [5482] = {n="Doom Weed", d="Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.", objs={"Doom Weed"}},
    [5501] = {n="Bone Collector", d="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.", objs={"Kodo Bones"}},
    [5511] = {n="The Key to Scholomance"},
    [5514] = {n="Mold Rhymes With...", d="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."},
    [5518] = {n="The Gordok Ogre Suit", d="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", objs={"Felsteel Chest", "Ogre Tannin Basket", "Knot Thimblejack's Cache"}},
    [5525] = {n="Free Knot!", d="Loot from: Gordok Brute, Gordok Mage-Lord, Gordok Captain", tgo={{"Gordok Brute", "Gordok Mage-Lord", "Gordok Captain"}}},
    [5526] = {n="Shards of the Felvine", d="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."},
    [5527] = {n="A Reliquary of Purity", d="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", objs={"Dusty Reliquary"}},
    [5528] = {n="The Gordok Taste Test"},
    [5529] = {n="Plagued Hatchlings", d="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", tgo={{"Plagued Hatchling"}}},
    [5534] = {n="Kim'jael's \"Missing\" Equipment", d="Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.", tgo={{"Spitelash Siren", "Spitelash Myrmidon", "Spitelash Battlemaster"}}},
    [5535] = {n="Spiritual Unrest", d="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.", tgo={{"Highborne Apparition"}, {"Highborne Lichling"}}},
    [5536] = {n="A Land Filled with Hatred", d="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.", tgo={{"Haldarr Satyr"}, {"Haldarr Trickster"}, {"Haldarr Felsworn"}}},
    [5542] = {n="Demon Dogs", d="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tgo={{"Plaguehound Runt"}, {"Plaguehound"}, {"Frenzied Plaguehound"}}},
    [5543] = {n="Blood Tinged Skies", d="Slay 30 Plaguebats and return to Tirion Fordring.", tgo={{"Plaguebat"}}},
    [5544] = {n="Carrion Grubbage", d="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tgo={{"Carrion Grub", "Carrion Devourer"}}},
    [5561] = {n="Kodo Roundup", d="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp."},
    [5581] = {n="Portals of the Legion", d="Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.", tgo={{"Demon Portal Guardian"}}},
    [5601] = {n="Sister Pamela", d="Find Pamela Redpath in Darrowshire."},
    [5648] = {n="Garments of Spirituality", d="Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.", tgo={{"Grunt Kor'ja"}}},
    [5649] = {n="In Favor of Spirituality", d="Speak to Tai'jin in Durotar."},
    [5650] = {n="Garments of Darkness", d="Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.", tgo={{"Deathguard Kel"}}},
    [5651] = {n="In Favor of Darkness", d="Speak to Dark Cleric Beryl in Tirisfal Glades."},
    [5652] = {n="Hex of Weakness"},
    [5654] = {n="Hex of Weakness", d="Speak to Ur'kyo in Orgrimmar."},
    [5658] = {n="Touch of Weakness"},
    [5679] = {n="Dark Sacrifice"},
    [5680] = {n="Shadowguard"},
    [5722] = {n="Searching for the Lost Satchel", d="Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."},
    [5723] = {n="Testing an Enemy's Strength", d="Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", tgo={{"Ragefire Trogg"}, {"Ragefire Shaman"}}},
    [5724] = {n="Returning the Lost Satchel", d="Take the Grimtotem Satchel to Rahauro in Thunder Bluff."},
    [5725] = {n="The Power to Destroy...", d="Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", tgo={{"Searing Blade Cultist", "Searing Blade Warlock"}, {"Searing Blade Cultist", "Searing Blade Warlock"}}},
    [5726] = {n="Hidden Enemies", d="Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", tgo={{"Burning Blade Fanatic", "Burning Blade Apprentice"}}},
    [5727] = {n="Hidden Enemies", d="Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", tgo={{"Neeru Fireblade"}}},
    [5728] = {n="Hidden Enemies", d="Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", tgo={{"Bazzalan"}, {"Jergosh the Invoker"}}},
    [5729] = {n="Hidden Enemies", d="Speak to Neeru Fireblade in Orgrimmar."},
    [5730] = {n="Hidden Enemies", d="Speak to Thrall in Orgrimmar and tell him what you've learned."},
    [5741] = {n="Sceptre of Light", d="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.", tgo={{"Burning Blade Seer"}}},
    [5742] = {n="Redemption", d="Listen to what Tirion Fordring has to say.", tgo={{"Tirion Fordring"}}},
    [5761] = {n="Slaying the Beast", d="Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", tgo={{"Taragaman the Hungerer"}}},
    [5762] = {n="Hemet Nesingwary", d="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."},
    [5763] = {n="Hunting in Stranglethorn", d="Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn."},
    [5781] = {n="Of Forgotten Memories", d="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tgo={{"Mercutio Filthgorger"}}},
    [5802] = {n="Fire Plume Forged", d="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\nBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.", objs={"Fire Plume Ridge Lava Lake"}},
    [5804] = {n="Araj's Scarab", d="Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.", objs={"Araj's Phylactery"}},
    [5843] = {n="Welcome!", d="Bring the Valley of Trials Gift Voucher to Magga."},
    [5844] = {n="Welcome!", d="Bring the Camp Narache Gift Voucher to Vorn Skyseer."},
    [5845] = {n="Of Lost Honor", d="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", objs={"Symbol of Lost Honor"}},
    [5846] = {n="Of Love and Family", d="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
    [5848] = {n="Of Love and Family", d="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\nReturn the painting to Tirion Fordring.", objs={"Unfinished Painting"}},
    [5863] = {n="The Dunemaul Compound", d="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", tgo={{"Dunemaul Brute"}, {"Dunemaul Enforcer"}, {"Gor'marok the Ravager"}}},
    [5881] = {n="Calling in the Reserves", d="Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens."},
    [5901] = {n="A Plague Upon Thee", d="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.", objs={"Large Termite Mound"}},
    [5902] = {n="A Plague Upon Thee", d="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."},
    [5922] = {n="Moonglade", d="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."},
    [5926] = {n="Heeding the Call", d="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
    [5927] = {n="Heeding the Call", d="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
    [5928] = {n="Heeding the Call", d="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
    [5930] = {n="Great Bear Spirit", d="Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", tgo={{"Great Bear Spirit"}}},
    [5932] = {n="Back to Thunder Bluff", d="Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."},
    [6002] = {n="Body and Heart", d="Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\nSpeak with Turak Runetotem in Thunder Bluff when you are done.", tgo={{"Lunaclaw Spirit"}}},
    [6022] = {n="To Kill With Purpose", d="Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot."},
    [6027] = {n="Book of the Ancients", d="Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.", tgo={{"Lord Kragaru"}}},
    [6029] = {n="The Everlook Report", d="Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands."},
    [6030] = {n="Duke Nicholas Zverenhoff", d="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."},
    [6042] = {n="Un-Life's Little Annoyances", d="Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", tgo={{"Noxious Plaguebat"}, {"Monstrous Plaguebat"}}},
    [6061] = {n="Taming the Beast", d="Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", tgo={{"Adult Plainstrider"}}},
    [6062] = {n="Taming the Beast", d="Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.", tgo={{"Dire Mottled Boar"}}},
    [6065] = {n="The Hunter's Path", d="Speak with Yaw Sharpmane in Bloodhoof Village."},
    [6066] = {n="The Hunter's Path", d="Speak with Yaw Sharpmane in Bloodhoof Village."},
    [6067] = {n="The Hunter's Path", d="Speak with Yaw Sharpmane in Bloodhoof Village."},
    [6068] = {n="The Hunter's Path", d="Speak with Thotar at Razor Hill."},
    [6069] = {n="The Hunter's Path", d="Speak with Thotar at Razor Hill."},
    [6070] = {n="The Hunter's Path", d="Speak with Thotar at Razor Hill."},
    [6081] = {n="Training the Beast", d="Speak with Ormak Grimshot in Orgrimmar."},
    [6082] = {n="Taming the Beast", d="Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.", tgo={{"Armored Scorpid"}}},
    [6083] = {n="Taming the Beast", d="Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.", tgo={{"Surf Crawler"}}},
    [6087] = {n="Taming the Beast", d="Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", tgo={{"Prairie Stalker"}}},
    [6088] = {n="Taming the Beast", d="Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", tgo={{"Swoop"}}},
    [6089] = {n="Training the Beast", d="Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."},
    [6126] = {n="Lessons Anew", d="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."},
    [6127] = {n="The Principal Source", d="Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.", objs={"Dreadmist Peak Pool"}},
    [6128] = {n="Gathering the Cure", d="Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.", tgo={{"Lasher Sproutling", "Wrathvine"}, {"Lost Barrens Kodo", "Barrens Kodo"}}},
    [6129] = {n="Curing the Sick", d="Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.", tgo={{"Sickly Gazelle"}}},
    [6130] = {n="Power over Poison", d="Return to Turak Runetotem on the Elder Rise, Thunder Bluff."},
    [6134] = {n="Ghost-o-plasm Round Up", d="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", tgo={{"Centaur Spectre"}}},
    [6142] = {n="Clam Bait", d="Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.", tgo={{"Enraged Reef Crawler"}}},
    [6143] = {n="Other Fish to Fry", d="Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.", tgo={{"Slitherblade Myrmidon"}, {"Slitherblade Naga"}, {"Slitherblade Sorceress"}}},
    [6161] = {n="Claim Rackmore's Treasure!", d="Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest.", tgo={{"Drysnap Crawler", "Drysnap Pincer"}, {"Slitherblade Naga", "Slitherblade Sorceress", "Slitherblade Warrior"}}},
    [6162] = {n="A Husband's Last Battle", d="Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.", tgo={{"Overlord Ror"}}},
    [6164] = {n="Augustus' Receipt Book", d="Bring Augustus' Receipt Book to Augustus the Touched in Terrordale.", objs={"Augustus' Receipt Book"}},
    [6282] = {n="Harpies Threaten", d="Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", tgo={{"Bloodfury Harpy"}, {"Bloodfury Ambusher"}, {"Bloodfury Slayer"}, {"Bloodfury Roguefeather"}}},
    [6283] = {n="Bloodfury Bloodline", d="Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.", tgo={{"Bloodfury Ripper"}}},
    [6284] = {n="Arachnophobia", d="Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.", tgo={{"Besseleth"}}},
    [6301] = {n="Cycle of Rebirth", d="Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.", objs={"Gaea Seed"}},
    [6381] = {n="New Life", d="Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.", objs={"Gaea Dirt Mound"}},
    [6382] = {n="The Ashenvale Hunt", d="Speak with Senani Thunderheart at Splintertree Post, Ashenvale."},
    [6383] = {n="The Ashenvale Hunt"},
    [6390] = {n="A Plague Upon Thee", d="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades."},
    [6393] = {n="Elemental War", d="Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.", tgo={{"Rogue Flame Spirit", "Burning Ravager", "Burning Destroyer"}}},
    [6394] = {n="Thazz'ril's Pick", d="Bring Thazz'ril's Pick to Foreman Thazz'ril.", objs={"Thazz'ril's Pick"}},
    [6395] = {n="Marla's Last Wish", d="Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.", objs={"Marla's Grave"}},
    [6421] = {n="Boulderslide Ravine", d="Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.", objs={"Resonite Crystal"}},
    [6441] = {n="Satyr Horns", d="Collect 16 Satyr Horns for Pixel in Splintertree Post.", tgo={{"Xavian Rogue", "Xavian Betrayer", "Xavian Felsworn"}}},
    [6442] = {n="Naga at the Zoram Strand", d="Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.", tgo={{"Wrathtail Myrmidon", "Wrathtail Razortail", "Wrathtail Wave Rider"}}},
    [6461] = {n="Blood Feeders", d="Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.", tgo={{"Deepmoss Creeper"}, {"Deepmoss Venomspitter"}}},
    [6462] = {n="Troll Charm", d="Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.", objs={"Troll Chest"}},
    [6481] = {n="Earthen Arise", d="Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.", tgo={{"Goggeroc"}}},
    [6482] = {n="Freedom to Ruul", d="Escort Ruul, then speak with Yama Snowhoof in Splintertree Post."},
    [6503] = {n="Ashenvale Outrunners", d="Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.", tgo={{"Ashenvale Outrunner"}}},
    [6504] = {n="The Lost Pages", d="Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post."},
    [6521] = {n="An Unholy Alliance", d="Bring Ambassador Malcin's Head to Varimathras in the Undercity.", tgo={{"Ambassador Malcin"}}},
    [6522] = {n="An Unholy Alliance", d="Take the Small Scroll to Varimathras in the Undercity."},
    [6541] = {n="Report to Kadrak", d="Report to Kadrak at the watch tower in northern Barrens."},
    [6543] = {n="The Warsong Reports", d="Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens."},
    [6544] = {n="Torek's Assault", d="Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post."},
    [6545] = {n="Warsong Runner Update"},
    [6546] = {n="Warsong Outrider Update"},
    [6547] = {n="Warsong Scout Update"},
    [6561] = {n="Blackfathom Villainy", d="Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", tgo={{"Twilight Lord Kelris"}}},
    [6562] = {n="Trouble in the Deeps", d="Speak to Je'neu Sancrea in Ashenvale."},
    [6563] = {n="The Essence of Aku'Mai", d="Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", objs={"Sapphire of Aku'Mai"}},
    [6564] = {n="Allegiance to the Old Gods", d="Bring the Damp Note to Je'neu Sancrea in Ashenvale."},
    [6565] = {n="Allegiance to the Old Gods", d="Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", tgo={{"Lorgus Jett"}}},
    [6621] = {n="King of the Foulweald", d="Place Karang's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.", tgo={{"Chief Murgut"}}},
    [6626] = {n="A Host of Evil", d="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", tgo={{"Razorfen Battleguard"}, {"Razorfen Thornweaver"}, {"Death's Head Cultist"}}},
    [6627] = {n="Test of Lore", d="Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."},
    [6641] = {n="Vorsha the Lasher", d="Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\nIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher."},
    [6681] = {n="The Manor, Ravenholdt", d="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\nYour cunning will be tested along the way. Be prepared.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Syndicate Emblems", d="Loot from: Syndicate Assassin, Syndicate Conjuror, Syndicate Footpad", tgo={{"Syndicate Assassin", "Syndicate Conjuror", "Syndicate Footpad"}}},
    [6844] = {n="Umber, Archivist", d="Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade."},
    [6845] = {n="Uncovering Past Secrets", d="Speak with Rabine Saturna in the village of Nighthaven, Moonglade."},
    [6921] = {n="Amongst the Ruins", d="Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", objs={"Fathom Stone"}},
    [6922] = {n="Baron Aquanis", d="Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."},
    [6981] = {n="The Glowing Shard", d="Travel to Ratchet to find someone that can tell you more about the glowing shard.\nThen, deliver the shard as you are directed.", tgo={{"Sputtervalve"}}},
    [7003] = {n="Zapped Giants", d="Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", tgo={{"Land Walker", "Cliff Giant", "Shore Strider"}}},
    [7028] = {n="Twisted Evils", d="Collect 15 Theradric Crystal Carvings for Willow in Desolace.", tgo={{"Cursed Centaur", "Putridus Satyr", "Putridus Trickster"}}},
    [7029] = {n="Vyletongue Corruption", d="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", tgo={{"Noxxious Scion"}, {}}, objs={"Maraudon Orange Crystal Pool"}},
    [7044] = {n="Legends of Maraudon", d="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\nFind a way to speak with Celebras.", tgo={{"Lord Vyletongue"}, {"Noxxion", "Noxxion's Spawn"}}},
    [7046] = {n="The Scepter of Celebras", d="Assist Celebras the Redeemed while he creates the Scepter of Celebras.\nSpeak with him when the ritual is complete.", objs={"Incantation of Celebras"}},
    [7064] = {n="Corruption of Earth and Seed", d="Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", tgo={{"Princess Theradras"}}},
    [7066] = {n="Seed of Life", d="Seek out Remulos in Moonglade and give him the Seed of Life."},
    [7067] = {n="The Pariah's Instructions", d="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."},
    [7068] = {n="Shadowshard Fragments", d="Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", tgo={{"Shadowshard Rumbler", "Shadowshard Smasher", "Shadowshard Thunderer"}}},
    [7201] = {n="The Last Element", d="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", tgo={{"Molten War Golem", "Ragereaver Golem", "Warbringer Construct"}}},
    [7441] = {n="Pusillin and the Elder Azj'Tordin", d="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", tgo={{"Pusillin"}}},
    [7461] = {n="The Madness Within", d="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", tgo={{"Immol'thar"}, {"Prince Tortheldrin"}}},
    [7463] = {n="Arcane Refreshment", d="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", tgo={{"Hydrospawn"}}},
    [7481] = {n="Elven Legends", d="Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", objs={"Skeletal Remains of Telmius Dreamseeker"}},
    [7489] = {n="Lethtendris's Web", d="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", tgo={{"Lethtendris"}}},
    [7492] = {n="Camp Mojache", d="Speak with Talo Thornhoof at Camp Mojache in Feralas."},
    [7498] = {n="Garona: A Study on Stealth and Treachery", d="Return the book to its rightful owners."},
    [7499] = {n="Codex of Defense", d="Return the book to its rightful owners."},
    [7500] = {n="The Arcanist's Cookbook", d="Return the book to its rightful owners."},
    [7501] = {n="The Light and How To Swing It", d="Return the book to its rightful owners."},
    [7502] = {n="Harnessing Shadows", d="Return the book to its rightful owners."},
    [7503] = {n="The Greatest Race of Hunters", d="Return the book to its rightful owners."},
    [7504] = {n="Holy Bologna: What the Light Won't Tell You", d="Return the book to its rightful owners."},
    [7505] = {n="Frost Shock and You", d="Return the book to its rightful owners."},
    [7506] = {n="The Emerald Dream...", d="Return the book to its rightful owners."},
    [7601] = {n="What Niby Commands", d="Speak with Impsy in Felwood."},
    [7602] = {n="Flawless Fel Essence", d="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\nRecover the Flawless Fel Essences and return to Impsy in Felwood.", tgo={{"Legashi Satyr", "Legashi Rogue", "Legashi Hellcaller"}, {"Jaedenar Legionnaire"}, {"Felguard Sentry"}}},
    [7603] = {n="Kroshius' Infernal Core", d="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="WANTED: Overseer Maltorius", d="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", tgo={{"Overseer Maltorius"}}},
    [7721] = {n="Fuel for the Zapping", d="Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", tgo={{"Sea Elemental", "Sea Spray"}}},
    [7722] = {n="What the Flux?", d="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", objs={"Secret Plans: Fiery Flux"}},
    [7723] = {n="Curse These Fat Fingers", d="Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", tgo={{"Heavy War Golem"}}},
    [7724] = {n="Fiery Menace!", d="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", tgo={{"Searing Lava Spider"}}},
    [7727] = {n="Incendosaurs? Whateverosaur is More Like It", d="Hansel Heavyhands wants you to kill 20 Incendosaurs.\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", tgo={{"Incendosaur"}}},
    [7728] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass", d="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", tgo={{"Dark Iron Steamsmith"}, {"Dark Iron Lookout"}}},
    [7729] = {n="JOB OPPORTUNITY: Culling the Competition", d="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.", tgo={{"Dark Iron Taskmaster"}, {"Dark Iron Slaver"}}},
    [7730] = {n="Zukk'ash Infestation", d="Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", tgo={{"Zukk'ash Stinger", "Zukk'ash Wasp", "Zukk'ash Worker"}}},
    [7731] = {n="Stinglasher", d="Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", tgo={{"Stinglasher"}}},
    [7732] = {n="Zukk'ash Report", d="Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar."},
    [7734] = {n="Improved Quality", d="Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.", tgo={{"Rage Scar Yeti", "Elder Rage Scar", "Ferocious Rage Scar"}}},
    [7738] = {n="Perfect Yeti Hide", d="Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas."},
    [7761] = {n="Blackhand's Command", d="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate."},
    [7815] = {n="Snapjaws, Mon!", d="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task.", tgo={{"Saltwater Snapjaw"}}},
    [7816] = {n="Gammerita, Mon!", d="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.", tgo={{"Gammerita"}}},
    [7828] = {n="Stalking the Stalkers", d="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.\nMarkhor mentioned that the wolves hide in the wilds of the Hinterlands.", tgo={{"Silvermane Stalker"}, {"Silvermane Howler"}}},
    [7829] = {n="Hunt the Savages", d="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.", tgo={{"Savage Owlbeast"}}},
    [7830] = {n="Avenging the Fallen", d="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.", tgo={{"Razorbeak Skylord"}}},
    [7839] = {n="Vilebranch Hooligans", d="Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.\nYou recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock.", objs={"Slagtree's Lost Tools"}},
    [7840] = {n="Lard Lost His Lunch", d="Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", tgo={{"Vilebranch Kidnapper"}}},
    [7845] = {n="Kidnapped Elder Torntusk!", d="Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\nYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},
    [7846] = {n="Recover the Key!", d="Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key.", tgo={{"Hitah'ya the Keeper"}}},
    [7847] = {n="Return to Primal Torntusk", d="Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue."},
    [7848] = {n="Attunement to the Core", d="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", objs={"Core Fragment"}},
    [7849] = {n="Separation Anxiety", d="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.\nMarkhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", objs={"Pile of Skulls", "Pile of Bones"}},
    [7850] = {n="Dark Vessels", d="Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", objs={"Vessel of Tainted Blood"}},
    [7861] = {n="WANTED: Vile Priestess Hexx and Her Minions", d="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\nVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", tgo={{"Vile Priestess Hexx"}, {"Vilebranch Aman'zasi Guard"}}},
    [7862] = {n="Job Opening: Guard Captain of Revantusk Village", d="You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.\nShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", tgo={{"Vilebranch Berserker"}, {"Vilebranch Shadow Hunter"}, {"Vilebranch Blood Drinker"}, {"Vilebranch Soul Eater"}}, star={"Rune of the Guard Captain", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}},
    [7877] = {n="The Treasure of the Shen'dralar", d="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
    [8151] = {n="The Hunter's Charm", d="Speak to Ogtinc in Azshara."},
    [8153] = {n="Courser Antlers", d="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", tgo={{"Mosshoof Courser"}}},
